advanced_config:
# Unenter Multi-Zone Enhanced Buffers & Header Limits
proxy_buffer_size 128k;
proxy_buffers 4 256k;
proxy_busy_buffers_size 256k;
large_client_header_buffers 8 64k;
client_max_body_size 100M;

# Outage-friendly error page: if an upstream endpoint on any UNAXIS
# environment is unreachable, redirect visitors to the independently hosted
# status page instead of NPM's raw 502. Preserve only the failed public host;
# the status app validates it before rendering a retry link.
error_page 502 503 504 = @status_redirect;
location @status_redirect {
    return 302 https://status.unenter.live/?from=$host&reason=upstream-unavailable;
}
